package com.learn.hub.persistence;

import jakarta.persistence.Column;
import jakarta.persistence.Entity;
import jakarta.persistence.GeneratedValue;
import jakarta.persistence.GenerationType;
import jakarta.persistence.Id;
import jakarta.persistence.Table;
import jakarta.persistence.Version;

import java.time.LocalDateTime;

@Entity
@Table(name = "topic")
public class TopicEntity {

    @Id
    @GeneratedValue(strategy = GenerationType.IDENTITY)
    private Long id;

    @Column(nullable = false, unique = true, length = 120)
    private String slug;

    @Column(nullable = false, length = 200)
    private String title;

    @Column(nullable = false, length = 64)
    private String category;

    @Version
    private long version;

    @Column(name = "updated_at", nullable = false)
    private LocalDateTime updatedAt;

    protected TopicEntity() {
    }

    public void rename(String title, LocalDateTime now) {
        this.title = title;
        this.updatedAt = now;
    }
}

package com.learn.hub.persistence;

import org.springframework.data.domain.Page;
import org.springframework.data.domain.Pageable;
import org.springframework.data.jpa.repository.JpaRepository;
import org.springframework.data.jpa.repository.Query;
import org.springframework.data.repository.query.Param;

import java.util.List;
import java.util.Optional;

public interface TopicRepository extends JpaRepository<TopicEntity, Long> {

    Optional<TopicEntity> findBySlug(String slug);

    boolean existsBySlug(String slug);

    Page<TopicEntity> findByCategoryAndStatus(String category, String status, Pageable pageable);

    @Query("select t.slug as slug, t.title as title from TopicEntity t where t.category = :category")
    List<TopicSummaryView> findSummaries(@Param("category") String category);

    interface TopicSummaryView {
        String getSlug();

        String getTitle();
    }
}
